Q: I have the idea but no coding skills – how do I build this animated UI? A: <p>Here, you can just copy-paste this into your html file and it should work. Let me know if somethings off, or not how you wanted!</p>
<pre><code>&lt;!DOCTYPE html&gt;
&lt;html lang=&quot;hu&quot;&gt;
&lt;head&gt;
&lt;meta charset=&quot;UTF-8&quot;&gt;
&lt;title&gt;Question of lamafesa&lt;/title&gt;
&lt;style&gt;
  body {
    margin: 0;
    height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    background: #111;
    overflow: hidden;
    font-family: Arial, sans-serif;
    color: white;
  }

  .background-orbs {
    position: absolute;
    width: 100%;
    height: 100%;
    overflow: hidden;
  }

  .orb {
    position: absolute;
    width: 100px;
    height: 100px;
    border-radius: 50%;
    opacity: 0.1;
    filter: blur(30px);
    animation: float 10s infinite linear;
  }

  @keyframes float {
    0% { transform: translateY(0) translateX(0); }
    50% { transform: translateY(-50px) translateX(50px); }
    100% { transform: translateY(0) translateX(0); }
  }

  .ui-container {
    position: relative;
    text-align: center;
    z-index: 1;
  }

  .mic-wrapper {
    display: inline-block;
    transition: transform 0.2s ease-in-out;
  }

  .microphone {
    width: 100px;
    height: 150px;
    background: white;
    border-radius: 50px;
    margin: 0 auto;
    transition: all 0.2s ease-in-out;
  }

  .status-text {
    margin-top: 20px;
    font-size: 1.2rem;
  }
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;

&lt;div class=&quot;background-orbs&quot;&gt;
  &lt;div class=&quot;orb&quot; style=&quot;background:red; top:30%; left:20%; animation-duration:12s;&quot;&gt;&lt;/div&gt;
  &lt;div class=&quot;orb&quot; style=&quot;background:yellow; top:60%; left:70%; animation-duration:15s;&quot;&gt;&lt;/div&gt;
  &lt;div class=&quot;orb&quot; style=&quot;background:green; top:50%; left:40%; animation-duration:18s;&quot;&gt;&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;ui-container&quot;&gt;
  &lt;div class=&quot;mic-wrapper&quot;&gt;
    &lt;div class=&quot;microphone&quot;&gt;&lt;/div&gt;
  &lt;/div&gt;
  &lt;div class=&quot;status-text&quot;&gt;On hold…&lt;/div&gt;
&lt;/div&gt;

&lt;script&gt;
const mic = document.querySelector('.microphone');
const wrapper = document.querySelector('.mic-wrapper');
const text = document.querySelector('.status-text');

let phase = 1;

function nextPhase() {
  if (phase === 1) {
    phase = 2;
    text.textContent = &quot;Ready to talk!&quot;;
    mic.style.background = &quot;linear-gradient(to top, blue, red, yellow, green)&quot;;
    mic.style.height = &quot;150px&quot;;
    mic.style.width = &quot;100px&quot;;
    mic.style.borderRadius = &quot;50px&quot;;
  } else if (phase === 2) {
    phase = 3;
    text.textContent = &quot;Processing…&quot;;
    mic.style.borderRadius = &quot;50%&quot;;
    mic.style.width = &quot;120px&quot;;
    mic.style.height = &quot;120px&quot;;
    mic.style.background = &quot;conic-gradient(blue, red, yellow, green)&quot;;
    startAudioReaction(); 
  }
}

setInterval(nextPhase, 3000);

async function startAudioReaction() {
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const audioContext = new (window.AudioContext || window.webkitAudioContext)();
    const source = audioContext.createMediaStreamSource(stream);
    const analyser = audioContext.createAnalyser();
    analyser.fftSize = 256;
    source.connect(analyser);

    const dataArray = new Uint8Array(analyser.frequencyBinCount);

    function animate() {
      analyser.getByteFrequencyData(dataArray);

      let sum = 0;
      for (let i = 0; i &lt; dataArray.length; i++) sum += dataArray[i];
      let avg = sum / dataArray.length;

      let scale = 1 + (avg / 256); // eredeti: 1 + avg/512 → érzékenyebb

      mic.style.transform = `scale(${scale})`; // Pulzus méret
      wrapper.style.transform = `rotate(${performance.now()/50}deg)`; // Forgás

      requestAnimationFrame(animate);
    }

    animate();
  } catch (err) {
    console.error(&quot;Error:&quot;, err);
  }
}
&lt;/script&gt;

&lt;/body&gt;
&lt;/html&gt;
</code></pre>
